28	describe("services/billing-service", () => {
29	  // checkLimit reads the ceiling from getPlanLimits(), never a hard-coded number.
30	  it("computes remaining and exceeded from the plan's quota", async () => {
31	    const tenant = await createTenant("billing-remaining", "starter");
32	    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 4 });
33	
34	    const check = await billingService.checkLimit(tenant.org.id, "seats", 1);
35	
36	    expect(check.plan).toBe("starter");
37	    expect(check.limit).toBe(10);
38	    expect(check.used).toBe(4);
39	    expect(check.remaining).toBe(6);
40	    expect(check.exceeded).toBe(false);
41	  });
42	
43	  // At exactly the quota the resource is exceeded and remaining is zero.
44	  it("marks a resource exceeded at, not past, the quota", async () => {
45	    const tenant = await createTenant("billing-exact", "starter");
46	    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 10 });
47	
48	    const check = await billingService.checkLimit(tenant.org.id, "seats");
49	
50	    expect(check.limit).toBe(10);
51	    expect(check.used).toBe(10);
52	    expect(check.remaining).toBe(0);
53	    expect(check.exceeded).toBe(true);
54	  });
55	
56	  // An unlimited enterprise quota is never exceeded and reports Infinity remaining.
57	  it("never marks an unlimited quota exceeded", async () => {
58	    const tenant = await createTenant("billing-unlimited", "enterprise");
59	    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 1_000_000 });
60	
61	    const check = await billingService.checkLimit(tenant.org.id, "seats", 500);
62	
63	    expect(check.limit).toBe(Number.POSITIVE_INFINITY);
64	    expect(check.exceeded).toBe(false);
65	    expect(check.remaining).toBe(Number.POSITIVE_INFINITY);
66	  });
67	
68	  // A downgrade whose current usage breaches the target plan is refused.
69	  it("refuses a downgrade that current usage would breach", async () => {
70	    const tenant = await createTenant("billing-downgrade", "growth");
71	    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });
72	
73	    await expect(
74	      billingService.changePlan(tenant.actors.owner, {
75	        orgId: tenant.org.id,
76	        plan: "free",
77	        interval: "monthly",
78	      }),
79	    ).rejects.toThrow(/seats exceeds its limit/);
80	  });
