 * The whole megabytes one stored file is charged against `storageMb`: its size
 * rounded up, so a 0.3 MB file costs 1 MB. Upload, removal and the recount all
 * charge through here so they can never disagree about a file's cost.
 */
export function storageMbFor(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
