  it("gives back exactly what was charged, and refuses unknown or foreign ids", async () => {
    const tenant = await createTenant("sto-remove", "free");
    const issue = await newIssue(tenant);
    const small = await upload(tenant, issue.id, FOUR_HUNDRED_KB);
    const medium = await upload(tenant, issue.id, ONE_HALF_MB);
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(3);

    await attachmentService.removeAttachment(tenant.actors.owner, {
      orgId: tenant.org.id,
      attachmentId: small.id,
    });
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(2);

    await attachmentService.removeAttachment(tenant.actors.owner, {
      orgId: tenant.org.id,
      attachmentId: medium.id,
    });
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(0);

    await expect(
      attachmentService.removeAttachment(tenant.actors.owner, {
        orgId: tenant.org.id,
        attachmentId: medium.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const other = await createTenant("sto-remove-other", "free");
    const otherIssue = await newIssue(other);
    const foreign = await upload(other, otherIssue.id, HALF_MB);
    const before = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;
    await expect(
      attachmentService.removeAttachment(tenant.actors.owner, {
        orgId: tenant.org.id,
        attachmentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(before);
    expect(
      await attachmentRepo.findAttachmentById(other.org.id, foreign.id),
    ).not.toBeNull();
  });

  it("deletes files on archived issues and on old issues", async () => {
    const tenant = await createTenant("sto-reach", "growth");
    const archived = await newIssue(tenant);
    const archivedFile = await upload(tenant, archived.id, FOUR_HUNDRED_KB);
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archived.id);
    await attachmentService.removeAttachment(tenant.actors.owner, {
      orgId: tenant.org.id,
      attachmentId: archivedFile.id,
    });

    const old = await newIssue(tenant);
    const oldFile = await upload(tenant, old.id, ONE_HALF_MB);
    for (let i = 0; i < 105; i += 1) {
      await newIssue(tenant);
    }
    await attachmentService.removeAttachment(tenant.actors.owner, {
      orgId: tenant.org.id,
      attachmentId: oldFile.id,
    });
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(0);
  });

  it("refuses an upload only past the limit, not at it", async () => {
    const tenant = await createTenant("sto-limit", "free");
    const issue = await newIssue(tenant);
    for (let i = 0; i < 4; i += 1) {
      await upload(tenant, issue.id, 25 * MB);
    }
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(100);
    await expect(upload(tenant, issue.id, 1)).rejects.toThrow(/no room/);
  });

  it("checks uploads against the subscription plan", async () => {
    const tenant = await createTenant("sto-sub", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "free", "monthly");
    const issue = await newIssue(tenant);
    for (let i = 0; i < 4; i += 1) {
      await upload(tenant, issue.id, 25 * MB);
    }
    await expect(upload(tenant, issue.id, 1)).rejects.toThrow(/Plan free/);
  });
});

describe("scratch: trial expiry storage rule", () => {
  it("keeps the plan above Free storage and downgrades at exactly the limit", async () => {
    const over = await createTenant("trial-over", "starter");
    const overIssue = await newIssue(over);
    for (let i = 0; i < 4; i += 1) {
      await upload(over, overIssue.id, 25 * MB);
    }
    await upload(over, overIssue.id, MB);

    const exact = await createTenant("trial-exact", "starter");
    const exactIssue = await newIssue(exact);
    for (let i = 0; i < 4; i += 1) {
      await upload(exact, exactIssue.id, 25 * MB);
    }

    await runTrialExpiryJob(new Date(Date.now() + 60 * 24 * 60 * 60 * 1000));

    expect((await subscriptionRepo.findSubscription(over.org.id))?.plan).toBe("starter");
    expect((await subscriptionRepo.findSubscription(exact.org.id))?.plan).toBe("free");
  });
});

